package com.company.platform.order.application;
import com.company.platform.order.domain.*;import com.company.platform.order.infrastructure.*;import com.company.platform.order.domain.events.OrderEvent;import org.springframework.stereotype.Service;import java.time.Instant;import java.util.*;
@Service public class CheckoutOrchestrator{private final CommerceCheckoutPort commerce;private final OrderService orders;private final TenantContextProvider tenant;private final KafkaCheckoutEventPublisher events;public CheckoutOrchestrator(CommerceCheckoutPort c,OrderService o,TenantContextProvider t,KafkaCheckoutEventPublisher e){commerce=c;orders=o;tenant=t;events=e;}
 public Order execute(UUID cartId){UUID t=tenant.currentTenantId();events.publish("CheckoutStartedEvent",cartId,t);var cart=validate(cartId);List<OrderService.ItemCommand> lines=new ArrayList<>();for(var line:cart.items()){var p=commerce.activePrice(t,line.productId());if(p==null||!p.active())throw new CheckoutErrors.InactivePrice();if(!p.enabled())throw new CheckoutErrors.CheckoutValidationFailed("product is not enabled");if(!p.currency().equals(line.currency()))throw new CheckoutErrors.CheckoutValidationFailed("currency mismatch");String snapshot=(p.productName()==null?line.productName():p.productName())+"|sku="+(p.sku()==null?line.sku():p.sku());lines.add(new OrderService.ItemCommand(line.productId(),snapshot,line.quantity(),p.amount()));}events.publish("CommercialSnapshotCreatedEvent",cartId,t);Order order;try{order=orders.create(cart.customerId(),cart.storeId(),Currency.getInstance(cart.items().get(0).currency()),lines);}catch(Exception e){throw new CheckoutErrors.OrderCreationFailed(e);}commerce.completeCart(t,cartId);events.publish("ShoppingCartCompletedEvent",cartId,t);events.publish("OrderGeneratedEvent",order.id(),t);return order;}
 public CommerceCheckoutPort.ShoppingCart validate(UUID cartId){UUID t=tenant.currentTenantId();var c=commerce.loadCart(t,cartId);if(c==null)throw new CheckoutErrors.CartNotFound();if(!t.equals(c.tenantId()))throw new CheckoutErrors.InvalidTenant();if(!"ACTIVE".equals(c.status()))throw new CheckoutErrors.CartAlreadyCompleted();if(c.items()==null||c.items().isEmpty())throw new CheckoutErrors.CheckoutValidationFailed("cart is empty");if(c.customerId()==null)throw new CheckoutErrors.CheckoutValidationFailed("customer required");events.publish("CheckoutValidatedEvent",cartId,t);return c;}
}
